\begin{definition}[FJ-set]\label{def:fj}
An \emph{FJ-set} is a compact, connected, full plane continuum containing more than one point (full: its complement is connected). This is Kahn's definition (\texttt{intro.tex}, lines 254--255).
\end{definition}

\begin{definition}[\(\psi\)-polynomial-like map, after Kahn]\label{def:psiql}
A \emph{\(\psi\)-polynomial-like map of degree \(d\)} is a pair
\[ (i,f):(\mathbf U',K')\longrightarrow(\mathbf U,K) \]
such that: \(\mathbf U'\) and \(\mathbf U\) are disks; \(i:\mathbf U'\to\mathbf U\) is a holomorphic immersion; \(f:\mathbf U'\to\mathbf U\) is a proper holomorphic branched cover of degree \(d\); \(K\subset\mathbf U\) is an FJ-set; and the common inverse
\[ K'=i^{-1}(K)=f^{-1}(K) \]
is connected. (Paraphrased from \texttt{psiql2.tex}, lines 16--33; properness of \(f\) is used explicitly at line 38. Kahn--Lyubich restate the same disk, branched-cover, full-continuum, and common-inverse clauses in \texttt{psiql.tex}, lines 8--15.) For \(d=2\) we say \(\psi\)-quadratic-like.
\end{definition}

\begin{remark}[Plane-case exceptionality]\label{rem:plane-case}
When the target \(\mathbf U\) is the whole plane, removability forces \(i\) to be an isomorphism (\texttt{psiql2.tex}, lines 43--51). The counterexample of Theorem~\ref{thm:psiql-nogo} uses bounded hyperbolic disks and therefore does not fall into that exceptional case.
\end{remark}

\begin{definition}[The Blaschke quotient \(R\)]\label{def:blaschke-quotient}
Let
\[ r'=\frac{1287}{1000},\qquad d=16,\qquad r=(r')^{16}, \]
and set
\[ \mathcal A=\Bigl\{\tfrac{1+6i}{10},\ \tfrac{-3-i}{10},\ \tfrac{-7+2i}{10}\Bigr\},\qquad \mathcal B=\Bigl\{\tfrac{-6+2i}{10},\ \tfrac{4i}{10}\Bigr\}, \]
\[ R(z)=\frac{\prod_{a\in\mathcal A}B_a(z)}{\prod_{b\in\mathcal B}B_b(z)}. \tag{A.1} \]
Clearing denominators, \(R=N/D_0\) where, in descending powers of \(z\),
\[\begin{aligned} N:\ & 2000+4000i,\ 19600+2200i,\ 28460-23880i,\ 4072-29046i,\\ &-6630-10210i,\ -1950-1525i, \end{aligned}\tag{A.2}\]
\[\begin{aligned} D_0:\ & 1525+1950i,\ 10210+6630i,\ 29046-4072i,\ 23880-28460i,\\ &-2200-19600i,\ -4000-2000i. \end{aligned}\tag{A.3}\]
Every coefficient is a Gaussian integer, so all subsequent sign and Rouch\'e checks are finite rational calculations.
\end{definition}

theorems.statement_latex:
\begin{lemma}\label{lem:avoid}
The map \(R\) of Definition~\ref{def:blaschke-quotient} has no zero and no pole on the closed annulus \(1\le|z|\le r'\). In particular \(u(z)=\log|R(z)|\) is harmonic on an open neighborhood of \(\overline{\mathbb A(1,r')}\).
\end{lemma}

\begin{lemma}\label{lem:circle-homeo}
\(|R|\equiv1\) on \(\mathbb T\), and the restriction \(R|_{\mathbb T}:\mathbb T\to\mathbb T\) is an orientation-preserving homeomorphism of degree one; indeed \(\frac{d}{d\theta}\arg R(e^{i\theta})>0\) for every \(\theta\).
\end{lemma}

\begin{lemma}\label{lem:containment}
\(R(\mathbb A(1,r'))\subset\mathbb A(1,r)\); more precisely \(|R(z)|>1\) for \(1<|z|<r'\), \(|R(z)|>1\) on \(|z|=r'\), and \(|R(z)|<48<(r')^{16}=r\) for \(1<|z|<r'\). Moreover \(r'=r^{1/16}\) identically, the exact modulus relation of Kahn's annulus lemma.
\end{lemma}

\begin{lemma}\label{lem:immersion}
\(R'(z)\ne0\) for \(1<|z|<r'\); hence \(R\) is a holomorphic immersion on \(\mathbb A(1,r')\).
\end{lemma}

\begin{lemma}\label{lem:collision}
Let \(z_1=-1+\tfrac45 i\). Then \(1<|z_1|<r'\), and there exists \(z_2\in\mathbb A(1,r')\) with \(z_2\ne z_1\) and \(R(z_2)=R(z_1)\). Hence \(R\) is not injective on \(\mathbb A(1,r')\).
\end{lemma}

\begin{theorem}\label{thm:annulus-nogo}
Let \(r'\), \(d=16\), \(r=(r')^{16}\), and \(R\) be as in Definition~\ref{def:blaschke-quotient}. Then
\[ R:\mathbb A(1,r')\longrightarrow\mathbb A(1,r) \]
is a holomorphic immersion, extends analytically across \(\mathbb T\), and restricts to an orientation-preserving degree-one homeomorphism \(\mathbb T\to\mathbb T\), with the exact modulus relation \(r'=r^{1/d}\) of Kahn's annulus lemma; but \(R\) is not injective. Consequently, the strengthening ``a holomorphic immersion \(I:\mathbb A(1,r^{1/d})\to\mathbb A(1,r)\) that extends to the inner circle with degree one must be globally injective'' is false, even when the inner-circle map is an orientation-preserving analytic homeomorphism.
\end{theorem}

theorems.proof_latex:
\begin{proof}
By Lemma~\ref{lem:avoid}, \(R\) is holomorphic and pole-free on a neighborhood of the closed annulus \(1\le|z|\le r'\); in particular it extends analytically across \(\mathbb T\). By Lemma~\ref{lem:containment}, \(R\) maps \(\mathbb A(1,r')\) into \(\mathbb A(1,r)\) with the exact relation \(r'=r^{1/16}\). By Lemma~\ref{lem:circle-homeo}, the boundary restriction is an orientation-preserving degree-one homeomorphism of \(\mathbb T\). By Lemma~\ref{lem:immersion}, \(R\) is an immersion on the source annulus. By Lemma~\ref{lem:collision}, two distinct source points have the same image. 
\end{proof}

